mapper.update:
UPDATE vm_air_plan_safety_officer_t
plan_id = #{planId}, safety_officer = #{safetyOfficer}, safety_officer_mobile = #{safetyOfficerMobile}, tenant_id = #{tenantId}, industry_code = #{industryCode}, update_user = #{updateUser}, update_time = now()
WHERE id = #{id}

mapper.select:
SELECT distinct safety_officer AS safetyOfficer, safety_officer_mobile AS safetyOfficerMobile FROM vm_air_plan_safety_officer_t WHERE delete_flag = '0' AND tenant_id = #{tenantId} AND industry_code = #{industryCode} AND create_user = #{createUser}
AND safety_officer LIKE CONCAT('%', #{safetyOfficer}, '%')
ORDER BY create_time DESC LIMIT 10
